"use client"
import * as React from "react"
import { ColorPickerPanel } from "./color-panel"
import { Button } from "@/components/ui/button"
import {
  Popover,
  PopoverTrigger,
  PopoverContent,
} from "@/components/ui/popover"
import {
  Sheet,
  SheetContent,
  SheetTitle,
  SheetDescription,
} from "@/components/ui/sheet"
import { barFieldVariants } from "@/components/ui/bar-field/bar-field"
import { useControllableState } from "@/hooks/use-controllable-state"
import {
  parseHex,
  rgbToHex,
  rgbToHsv,
  hsvToRgb,
  type HSV,
} from "@/lib/color"
import {
  ColorArea,
  ColorHueSlider,
  ColorAlphaSlider,
  ColorSwatch,
} from "./color-parts"
import { cn } from "@/lib/utils"
const defaultLabels = {
  open: "选择颜色",
  invalid: "请输入有效的 HEX 颜色",
  saturation: "饱和度",
  brightness: "明度",
  hue: "色相",
  alpha: "透明度",
  format: "颜色格式",
  presets: "预设色板",
  eyeDropper: "吸取屏幕颜色",
  done: "完成",
  red: "红",
  green: "绿",
  blue: "蓝",
  lightness: "亮度",
}
type ColorPickerLabels = typeof defaultLabels
type ColorPickerProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue" | "onChange"
> & {
  /** 方条标签；省略时提供 aria-label */ label?: React.ReactNode
  /** 受控 HEX */ value?: string
  /** 初始颜色 @default "#2563eb" */ defaultValue?: string
  /** 变化时持续触发 */ onValueChange?: (value: string) => void
  /** 操作结束触发 */ onValueCommit?: (value: string) => void
  /** 输出包含透明度 @default false */ alpha?: boolean
  /** 初始面板格式 @default "HEX" */ format?: "HEX" | "RGB" | "HSL"
  /** 预设颜色 @default [] */ presets?: string[]
  /** 中文文案覆盖 */ labels?: Partial<ColorPickerLabels>
  /** 高度档 @default "default" */ size?: "sm" | "default" | "lg"
  /** 禁用 @default false */ disabled?: boolean
  /** 只读 @default false */ readOnly?: boolean
  /** 错误信息 */ error?: string
  /** 说明 */ description?: React.ReactNode
  /** HEX 输入框的 id，方便外部 label 关联 */ id?: string
  /** 表单字段名 */ name?: string
  /** 所属表单 */ form?: string
}
function subscribe(notify: () => void) {
  const m = matchMedia("(pointer: coarse)")
  m.addEventListener("change", notify)
  return () => m.removeEventListener("change", notify)
}
function ColorPicker({
  id: idProp,
  label,
  value: prop,
  defaultValue = "#2563eb",
  onValueChange,
  onValueCommit,
  alpha = false,
  format: initialFormat = "HEX",
  presets = [],
  labels: overrides,
  size = "default",
  disabled,
  readOnly,
  error,
  description,
  name,
  form,
  className,
  ...props
}: ColorPickerProps) {
  const autoId = React.useId()
  const id = idProp ?? autoId
  const labels = { ...defaultLabels, ...overrides }
  const [value, setValue] = useControllableState({
    prop,
    defaultProp: defaultValue,
    onChange: onValueChange,
  })
  const [local, setLocal] = React.useState<HSV>(() =>
    rgbToHsv(parseHex(value) ?? parseHex("#2563eb")!),
  )
  const parsed = rgbToHsv(parseHex(value) ?? parseHex("#2563eb")!, local.h)
  const renderedHex = rgbToHex(hsvToRgb(local), alpha)
  const hsv =
    rgbToHex(parseHex(value) ?? hsvToRgb(local), alpha) === renderedHex
      ? local
      : parsed
  const [draft, setDraft] = React.useState<string | null>(null)
  const [invalid, setInvalid] = React.useState(false)
  const [format, setFormat] = React.useState(initialFormat)
  const [open, setOpen] = React.useState(false),
    [sheetOpen, setSheetOpen] = React.useState(false)
  const coarse = React.useSyncExternalStore(
    subscribe,
    () => matchMedia("(pointer: coarse)").matches,
    () => false,
  )
  const eye = React.useSyncExternalStore(
    () => () => {},
    () => "EyeDropper" in window,
    () => false,
  )
  const locked = !!(disabled || readOnly)
  const lockedRef = React.useRef(locked)
  React.useLayoutEffect(() => {
    lockedRef.current = locked
  }, [locked])
  const [wasLocked, setWasLocked] = React.useState(locked)
  if (wasLocked !== locked) {
    setWasLocked(locked)
    if (locked) {
      setOpen(false)
      setSheetOpen(false)
      setDraft(null)
      setInvalid(false)
    }
  }
  // 面板关闭时丢弃无效草稿，回到当前颜色；有效草稿仍由失焦提交
  const panelOpen = coarse ? sheetOpen : open
  const [wasPanelOpen, setWasPanelOpen] = React.useState(panelOpen)
  if (wasPanelOpen !== panelOpen) {
    setWasPanelOpen(panelOpen)
    if (!panelOpen) {
      if (draft !== null && !parseHex(draft, { alpha })) setDraft(null)
      setInvalid(false)
    }
  }
  function commit(hex: string) {
    if (!lockedRef.current) onValueCommit?.(hex)
  }
  const root = React.useRef<HTMLDivElement>(null)
  function change(next: HSV, shouldCommit = false) {
    if (lockedRef.current) return
    setLocal(next)
    const hex = rgbToHex(hsvToRgb(next), alpha)
    setValue(hex)
    setDraft(null)
    setInvalid(false)
    if (shouldCommit) onValueCommit?.(hex)
  }
  function submit(text: string) {
    if (lockedRef.current) return
    const rgb = parseHex(text, { alpha })
    if (!rgb) {
      setInvalid(true)
      return
    }
    change(rgbToHsv(rgb, local.h), true)
  }
  React.useEffect(() => {
    const el =
      root.current?.closest("form") ??
      (form ? document.getElementById(form) : null)
    const reset = () => {
      if (prop === undefined) {
        const next = rgbToHsv(parseHex(defaultValue)!)
        setLocal(next)
        setValue(rgbToHex(hsvToRgb(next), alpha))
        setDraft(null)
        setInvalid(false)
      }
    }
    el?.addEventListener("reset", reset)
    return () => el?.removeEventListener("reset", reset)
  }, [prop, defaultValue, form, setValue, alpha])
  const hex = rgbToHex(hsvToRgb(hsv), alpha)
  const panel = (
    <ColorPickerPanel
      {...{
        presets,
        hsv,
        hex,
        alpha,
        labels,
        format,
        setFormat,
        draft,
        setDraft,
        invalid,
        submit,
        change,
        onValueCommit: commit,
        locked,
        eye,
        coarse,
        setSheetOpen,
      }}
    />
  )
  const trigger = (
    <Button
      type="button"
      size={size === "sm" ? "icon-sm" : size === "lg" ? "icon-lg" : "icon"}
      variant="ghost"
      disabled={disabled || readOnly}
      aria-label={labels.open}
      aria-haspopup="dialog"
      aria-expanded={coarse ? sheetOpen : open}
      className="shrink-0 focus-visible:ring-inset"
      onClick={() => {
        if (coarse) setSheetOpen(true)
      }}
    >
      <ColorSwatch color={hex} />
    </Button>
  )
  return (
    <div
      {...props}
      ref={root}
      data-slot="color-picker"
      className={cn(
        "w-full min-w-0 in-data-[slot=grid-toolbar]:h-full",
        className,
      )}
    >
      <Popover
        open={!locked && !coarse && open}
        onOpenChange={(next) => setOpen(next && !lockedRef.current)}
      >
        <div className="@container/color-picker flex h-full flex-col gap-1.5">
          {label && (
            <label
              htmlFor={id}
              aria-hidden
              className="hidden text-xs text-muted-foreground in-data-[slot=grid-toolbar]:hidden! @max-[20rem]/color-picker:block"
            >
              {label}
            </label>
          )}
          <div
            data-slot="color-picker-control"
            className={cn(
              barFieldVariants({ size }),
              // 与 bar-field 同一套状态样式
              invalid || error
                ? "border-destructive ring-3 ring-destructive/20 dark:border-destructive/50 dark:ring-destructive/40"
                : "border-edge focus-within:border-foreground/25 focus-within:bg-background hover:not-focus-within:bg-muted dark:focus-within:bg-input/30",
              disabled && "opacity-50",
              // 面板打开时方条保持高亮：鼠标移进面板后，仍看得出面板属于这一条
              panelOpen && "bg-muted in-data-[slot=grid-toolbar]:bg-muted",
            )}
          >
            {label && (
              <label
                htmlFor={id}
                // mr-auto 把色块与 HEX 推到右侧，与方条文本框「标签靠左、值靠右」一致
                className="mr-auto shrink-0 text-muted-foreground in-data-[slot=grid-toolbar]:not-sr-only! @max-[20rem]/color-picker:sr-only"
              >
                {label}
              </label>
            )}
            {coarse ? trigger : <PopoverTrigger render={trigger} />}
            <input
              id={id}
              disabled={disabled}
              readOnly={readOnly}
              aria-label={props["aria-label"]}
              aria-labelledby={props["aria-labelledby"]}
              aria-invalid={!!(invalid || error)}
              aria-describedby={
                invalid || error || description
                  ? `${id}-description`
                  : undefined
              }
              className={cn(
                "h-full min-w-0 bg-transparent font-mono text-base outline-none pointer-fine:md:text-sm",
                // 有标签时按 HEX 位数定宽（等宽字体），整组靠右；无标签或标签移到上方时占满剩余宽度
                label
                  ? cn(
                      alpha ? "w-[10ch]" : "w-[8ch]",
                      "@max-[20rem]/color-picker:flex-1",
                    )
                  : "flex-1",
              )}
              value={draft ?? hex}
              onChange={(e) => {
                setDraft(e.target.value)
                setInvalid(false)
              }}
              onBlur={() => {
                if (draft !== null) submit(draft)
              }}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault()
                  submit(draft ?? hex)
                }
              }}
            />
          </div>
          {(invalid || error || description) && (
            <p
              id={`${id}-description`}
              className={cn(
                "text-xs",
                invalid || error ? "text-destructive" : "text-muted-foreground",
              )}
            >
              {invalid ? labels.invalid : (error ?? description)}
            </p>
          )}
        </div>
        {!coarse && (
          <PopoverContent
            aria-label={labels.open}
            className="w-72 max-w-[calc(100vw-2rem)]"
          >
            {panel}
          </PopoverContent>
        )}
      </Popover>
      {coarse && (
        <Sheet
          open={!locked && sheetOpen}
          onOpenChange={(next) => setSheetOpen(next && !lockedRef.current)}
        >
          <SheetContent
            data-slot="color-picker-sheet"
            side="bottom"
            showCloseButton={false}
            className="max-h-[90dvh] overflow-y-auto p-4 pb-[max(1rem,env(safe-area-inset-bottom))]"
          >
            <SheetTitle>{label ?? labels.open}</SheetTitle>
            <SheetDescription className="sr-only">
              {labels.open}
            </SheetDescription>
            {panel}
          </SheetContent>
        </Sheet>
      )}
      {name && (
        <input
          type="hidden"
          name={name}
          form={form}
          value={hex}
          disabled={disabled}
        />
      )}
    </div>
  )
}
export { ColorPicker, ColorArea, ColorHueSlider, ColorAlphaSlider, ColorSwatch }
export type { ColorPickerProps, ColorPickerLabels }

"use client"
import * as React from "react"
import { Slider } from "@base-ui/react/slider"
import { cn } from "@/lib/utils"
import { clamp, hsvToRgb, rgbToHex, type HSV } from "@/lib/color"

const checker: React.CSSProperties = {
  backgroundColor: "var(--background)",
  backgroundImage:
    "conic-gradient(var(--muted) 25%, transparent 0 50%, var(--muted) 0 75%, transparent 0)",
  backgroundSize: "12px 12px",
}
function ColorSwatch({
  color,
  className,
  style,
  ...props
}: React.ComponentProps<"span"> & { color: string }) {
  return (
    <span
      data-slot="color-swatch"
      className={cn(
        "relative inline-block size-5 shrink-0 rounded-sm",
        className,
      )}
      style={{ ...checker, ...style }}
      {...props}
    >
      {/* 内描边画在颜色层之上：深色在暗色背景、浅色在亮色背景上都能看清色块边界 */}
      <span
        className="absolute inset-0 rounded-[inherit] ring-1 ring-foreground/20 ring-inset"
        style={{ background: color }}
      />
    </span>
  )
}
type AreaProps = Omit<React.ComponentProps<"div">, "onChange"> & {
  /** HSV 颜色 */ value: HSV
  /** 拖动及键盘变化 */ onValueChange: (value: HSV) => void
  /** 松手或按键结束 */ onValueCommit?: (value: HSV) => void
  /** 读屏名称 @default 中文 */ labels?: {
    saturation?: string
    brightness?: string
  }
}
function ColorArea({
  value,
  onValueChange,
  onValueCommit,
  labels,
  className,
  ...props
}: AreaProps) {
  const latest = React.useRef(value)
  React.useEffect(() => {
    latest.current = value
  }, [value])
  const frame = React.useRef<number>(0)
  React.useEffect(() => () => cancelAnimationFrame(frame.current), [])
  function update(e: React.PointerEvent<HTMLDivElement>) {
    const rect = e.currentTarget.getBoundingClientRect()
    const next = {
      ...latest.current,
      s: clamp((e.clientX - rect.left) / rect.width),
      v: 1 - clamp((e.clientY - rect.top) / rect.height),
    }
    latest.current = next
    cancelAnimationFrame(frame.current)
    frame.current = requestAnimationFrame(() => onValueChange(next))
  }
  return (
    <div
      data-slot="color-area"
      className={cn(
        "relative h-44 touch-none rounded-md select-none has-focus-visible:ring-3 has-focus-visible:ring-ring/50",
        className,
      )}
      style={{
        background: `linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, transparent), hsl(${value.h} 100% 50%)`,
      }}
      {...props}
      onPointerDown={(e) => {
        if (e.button !== 0) return
        e.preventDefault()
        e.currentTarget.setPointerCapture(e.pointerId)
        update(e)
      }}
      onPointerMove={(e) => {
        if (e.currentTarget.hasPointerCapture(e.pointerId)) update(e)
      }}
      onPointerUp={(e) => {
        if (!e.currentTarget.hasPointerCapture(e.pointerId)) return
        update(e)
        cancelAnimationFrame(frame.current)
        onValueChange(latest.current)
        onValueCommit?.(latest.current)
        e.currentTarget.releasePointerCapture(e.pointerId)
      }}
      onPointerCancel={() => {
        cancelAnimationFrame(frame.current)
        onValueCommit?.(latest.current)
      }}
    >
      <span
        aria-hidden
        className="pointer-events-none absolute size-3 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-background shadow-sm ring-1 ring-foreground"
        style={{ left: `${value.s * 100}%`, top: `${(1 - value.v) * 100}%` }}
      />
      {(["s", "v"] as const).map((key) => (
        <input
          key={key}
          type="range"
          className="sr-only"
          min={0}
          max={100}
          step={1}
          value={value[key] * 100}
          aria-label={
            key === "s"
              ? (labels?.saturation ?? "饱和度")
              : (labels?.brightness ?? "明度")
          }
          aria-valuetext={`${Math.round(value[key] * 100)}%`}
          onChange={(e) =>
            onValueChange({ ...value, [key]: Number(e.target.value) / 100 })
          }
          onKeyDown={(e) => {
            if (
              ![
                "ArrowLeft",
                "ArrowRight",
                "ArrowUp",
                "ArrowDown",
                "Home",
                "End",
              ].includes(e.key)
            )
              return
            e.preventDefault()
            const n =
              e.key === "Home"
                ? 0
                : e.key === "End"
                  ? 1
                  : clamp(
                      value[key] +
                        (["ArrowLeft", "ArrowDown"].includes(e.key) ? -1 : 1) *
                          (e.shiftKey ? 0.1 : 0.01),
                    )
            onValueChange({ ...value, [key]: n })
          }}
          onKeyUp={() => onValueCommit?.(latest.current)}
        />
      ))}
    </div>
  )
}
type ColorSliderProps = {
  /** 当前值 */ value: number
  /** 变化 */ onValueChange: (value: number) => void
  /** 提交 */ onValueCommit?: (value: number) => void
  /** 读屏名称 */ label?: string
  className?: string
}
function ColorTrack({
  value,
  onValueChange,
  onValueCommit,
  label,
  max,
  background,
  className,
}: ColorSliderProps & { max: number; background: string }) {
  return (
    <Slider.Root
      data-slot="color-track"
      min={0}
      max={max}
      step={max === 1 ? 0.01 : 1}
      value={value}
      onValueChange={(v) => onValueChange(v as number)}
      onValueCommitted={(v) => onValueCommit?.(v as number)}
      className={cn("w-full", className)}
    >
      <Slider.Control className="flex h-7 items-center pointer-coarse:h-11">
        <Slider.Track
          className="relative h-3 w-full rounded-full"
          style={{
            ...checker,
            backgroundImage: background,
            backgroundSize: "100% 100%, 12px 12px",
          }}
        >
          <Slider.Thumb
            aria-label={label}
            getAriaValueText={(v) =>
              `${label} ${Math.round(Number(v) * (max === 1 ? 100 : 1))}${max === 1 ? "%" : " 度"}`
            }
            className="size-4 rounded-full border-2 border-background bg-foreground shadow-sm outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
          />
        </Slider.Track>
      </Slider.Control>
    </Slider.Root>
  )
}
function ColorHueSlider(props: ColorSliderProps) {
  return (
    <ColorTrack
      {...props}
      label={props.label ?? "色相"}
      max={360}
      background="linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)"
    />
  )
}
function ColorAlphaSlider({
  color,
  ...props
}: ColorSliderProps & { color: HSV }) {
  return (
    <ColorTrack
      {...props}
      label={props.label ?? "透明度"}
      max={1}
      background={`linear-gradient(to right, transparent, ${rgbToHex(hsvToRgb({ ...color, a: 1 }))}), conic-gradient(var(--muted) 25%, transparent 0 50%, var(--muted) 0 75%, transparent 0)`}
    />
  )
}
export { ColorArea, ColorHueSlider, ColorAlphaSlider, ColorSwatch }
export type { AreaProps, ColorSliderProps }

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }

"use client"
import { Pipette } from "lucide-react"
import { Button } from "@/components/ui/button"
import { BarField } from "@/components/ui/bar-field/bar-field"
import {
  parseHex,
  hsvToRgb,
  hsvToHsl,
  hslToHsv,
  rgbToHsv,
  type HSV,
} from "@/lib/color"
import {
  ColorArea,
  ColorHueSlider,
  ColorAlphaSlider,
  ColorSwatch,
} from "./color-parts"
import type { ColorPickerLabels } from "./color-picker"
type PanelProps = {
  locked: boolean
  presets: string[]
  hsv: HSV
  hex: string
  alpha: boolean
  labels: ColorPickerLabels
  format: "HEX" | "RGB" | "HSL"
  setFormat: (value: "HEX" | "RGB" | "HSL") => void
  draft: string | null
  setDraft: (value: string) => void
  invalid: boolean
  submit: (value: string) => void
  change: (value: HSV, commit?: boolean) => void
  onValueCommit?: (value: string) => void
  eye: boolean
  coarse: boolean
  setSheetOpen: (value: boolean) => void
}
function ColorPickerPanel({
  locked,
  presets,
  hsv,
  hex,
  alpha,
  labels,
  format,
  setFormat,
  draft,
  setDraft,
  invalid,
  submit,
  change,
  onValueCommit,
  eye,
  coarse,
  setSheetOpen,
}: PanelProps) {
  const rgb = hsvToRgb(hsv),
    hsl = hsvToHsl(hsv)
  const channels =
    format === "RGB"
      ? [labels.red, labels.green, labels.blue]
      : [labels.hue, labels.saturation, labels.lightness]
  const values =
    format === "RGB" ? [rgb.r, rgb.g, rgb.b] : [hsl.h, hsl.s * 100, hsl.l * 100]
  return (
    <div
      inert={locked}
      data-slot="color-picker-panel"
      className="flex flex-col gap-2 p-2"
    >
      <ColorArea
        value={hsv}
        onValueChange={change}
        onValueCommit={(v) => change(v, true)}
        labels={labels}
      />
      <ColorHueSlider
        value={hsv.h}
        label={labels.hue}
        onValueChange={(h) => change({ ...hsv, h })}
        onValueCommit={(h) => change({ ...hsv, h }, true)}
      />
      {alpha && (
        <ColorAlphaSlider
          color={hsv}
          value={hsv.a}
          label={labels.alpha}
          onValueChange={(a) => change({ ...hsv, a })}
          onValueCommit={(a) => change({ ...hsv, a }, true)}
        />
      )}
      <div className="flex gap-1" role="group" aria-label={labels.format}>
        {(["HEX", "RGB", "HSL"] as const).map((f) => (
          <Button
            key={f}
            type="button"
            size="lg"
            variant={format === f ? "secondary" : "ghost"}
            aria-pressed={format === f}
            onClick={() => setFormat(f)}
          >
            {f}
          </Button>
        ))}
      </div>
      {format === "HEX" ? (
        <BarField
          aria-label="HEX"
          value={draft ?? hex}
          onValueChange={setDraft}
          error={invalid ? labels.invalid : undefined}
          onBlur={() => {
            if (draft !== null) submit(draft)
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault()
              submit(draft ?? hex)
            }
          }}
        />
      ) : (
        <div className="grid grid-cols-3 gap-2">
          {channels.map((c, i) => (
            <BarField
              key={`${format}-${c}`}
              label={c}
              type="number"
              min={0}
              max={format === "RGB" ? 255 : i === 0 ? 360 : 100}
              value={String(Math.round(values[i]))}
              onValueChange={(text) => {
                const n = Number(text)
                if (!Number.isFinite(n)) return
                if (format === "RGB") {
                  const next = {
                    ...rgb,
                    [["r", "g", "b"][i]]: Math.min(255, Math.max(0, n)),
                  }
                  change(rgbToHsv(next, hsv.h))
                } else {
                  change(
                    hslToHsv({
                      ...hsl,
                      [["h", "s", "l"][i]]:
                        Math.min(i === 0 ? 360 : 100, Math.max(0, n)) /
                        (i === 0 ? 1 : 100),
                    }),
                  )
                }
              }}
              onBlur={() => onValueCommit?.(hex)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault()
                  onValueCommit?.(hex)
                }
              }}
            />
          ))}
        </div>
      )}
      {presets.length > 0 && (
        <div
          role="group"
          aria-label={labels.presets}
          className="flex flex-wrap gap-1"
        >
          {presets
            .filter((c) => parseHex(c, { alpha }))
            .map((c) => (
              <Button
                key={c}
                type="button"
                variant="ghost"
                size="icon-lg"
                aria-label={c}
                onClick={() => submit(c)}
              >
                <ColorSwatch color={c} />
              </Button>
            ))}
        </div>
      )}
      {eye && (
        <Button
          type="button"
          variant="outline"
          size="lg"
          onClick={() => {
            const Constructor = (
              window as unknown as {
                EyeDropper: new () => {
                  open: () => Promise<{ sRGBHex: string }>
                }
              }
            ).EyeDropper
            new Constructor()
              .open()
              .then((result) => submit(result.sRGBHex))
              .catch(() => {})
          }}
        >
          <Pipette aria-hidden />
          {labels.eyeDropper}
        </Button>
      )}
      {coarse && (
        <Button type="button" size="lg" onClick={() => setSheetOpen(false)}>
          {labels.done}
        </Button>
      )}
    </div>
  )
}
export { ColorPickerPanel }
